export const ADMT_HOOK_CONTEXT_BLOCK: string =
"// ── [RATIFY — DRAFT, unratified] — the direction matrix (doc 213 §4 / doc\n// 222 §3 / doc 224, as data) ──────────────────────────────────────────────\n//\n// IDENTICAL in shape to LIA_HOOK_DIRECTION_MATRIX/DPIA/Risk's own copies —\n// this table transcribes `directionFor` (hook-types.ts, unmodified,\n// product-agnostic), which is the code every product's join actually\n// renders through. Reproduced here (not imported) so a byte-pin test can\n// catch the two drifting apart, mirroring the LIA/DPIA/Risk convention.\n\nexport interface AdmtHookMatrixRow {\n  readonly posture: string;\n  readonly fact_agreement: string;\n  readonly engine_verdict: string;\n  readonly shape: string;\n  readonly note: string;\n}\n\nexport const ADMT_HOOK_DIRECTION_MATRIX: readonly AdmtHookMatrixRow[] = [\n  { posture: \"accepted\", fact_agreement: \"same\", engine_verdict: \"any\", shape: \"S1 supports\", note: \"hedged to `likely` language; never lifts a determination\" },\n  { posture: \"accepted\", fact_agreement: \"different / unknown\", engine_verdict: \"any\", shape: \"omit\", note: \"nothing to say\" },\n  { posture: \"conditional\", fact_agreement: \"same\", engine_verdict: \"passes, and every condition_atom holds on the record\", shape: \"S5b recognised + condition satisfied\", note: \"the engine's pass is what satisfies the condition; the hook only echoes it\" },\n  { posture: \"conditional\", fact_agreement: \"same\", engine_verdict: \"otherwise (fails / uncertain, or condition_atoms null / not all held)\", shape: \"S5a recognised, condition unresolved\", note: \"the guidance is relevant; whether its condition is met is Section {section}'s own question — never asserted here\" },\n  { posture: \"conditional\", fact_agreement: \"different (a distinguishing pair holds)\", engine_verdict: \"passes\", shape: \"omit + flag `authority_not_dispositive` (`rule_missing` when the pair expressly excludes)\", note: \"a silent source under a pass is nothing missing; an express exclusion under a pass means a rule is missing\" },\n  { posture: \"conditional\", fact_agreement: \"different (a distinguishing pair holds)\", engine_verdict: \"fails / uncertain\", shape: \"S6 source silent (S6x where the pair expressly excludes)\", note: \"\\\"does not extend\\\" only from an authored `source_expressly_excludes` pair with a verified exclusion span\" },\n  { posture: \"conditional\", fact_agreement: \"unknown\", engine_verdict: \"any\", shape: \"omit\", note: \"\" },\n  { posture: \"rejected\", fact_agreement: \"same\", engine_verdict: \"fails / uncertain\", shape: \"S2 cuts against and applied\", note: \"the record's own determination already reflects it\" },\n  { posture: \"rejected\", fact_agreement: \"same\", engine_verdict: \"passes\", shape: \"omit + flag `rule_missing`\", note: \"the lawyer's rule: an adverse authority on the same facts under a pass means a rule is missing — never printed as risk noted\" },\n  { posture: \"rejected\", fact_agreement: \"different (a distinguishing pair holds)\", engine_verdict: \"any\", shape: \"S3 cuts against but distinguished\", note: \"renders only from the pair (source fact / record fact); never from an atom's generic phrase\" },\n  { posture: \"rejected\", fact_agreement: \"unknown\", engine_verdict: \"any\", shape: \"omit\", note: \"\" },\n  { posture: \"contested (R4)\", fact_agreement: \"same\", engine_verdict: \"any\", shape: \"S4 noted as a boundary\", note: \"prints the derived status and the appeal note; no relation drawn\" },\n  { posture: \"contested (R4)\", fact_agreement: \"different / unknown\", engine_verdict: \"any\", shape: \"omit\", note: \"a contested decision on different facts adds nothing\" },\n  { posture: \"any\", fact_agreement: \"unknown from atoms\", engine_verdict: \"—\", shape: \"the stored two-leg selection's agreement, if one exists; else omit + flag `selection_pending`; legs disagreed → omit + flag `selection_unsettled` (the ROO item)\", note: \"a call is made only where no stored decision exists AND the pre-filter says either answer could print\" },\n  { posture: \"any\", fact_agreement: \"`required_atoms` not all held\", engine_verdict: \"—\", shape: \"not nominated\", note: \"\" },\n];\n\n// ── [RATIFY — DRAFT, unratified] — the atom-phrase map ───────────────────\n//\n// One ratified clause per closed-list atom value in ADMT's own hook\n// vocabulary (`class:`, `flag:`, `state:intake.<path>=<value>` — no\n// `relationship:` or `data_category:` atoms exist for ADMT today; see\n// generate-corpus-hooks/_local/product-registry.ts's ADMT entry and doc\n// 235's own [NEEDS] on why). Every phrase is a short, plain-language,\n// third-person description of a record fact — doc 223B's CEO-register bar\n// (\"The company has stated that it processes browsing and behavioural\n// data...\" — short sentences, plain words), not LIA's original, more\n// formal drafting register.\n\nexport const ADMT_ATOM_PHRASES: Readonly<Record<string, string>> = {\n  // — classes (decision domain; RULE_PRODUCT_REGISTRY-style HOOK_PRODUCT_REGISTRY.admt.typed_state_vocabulary.classes) —\n  // A record's `use_case_class` is the FIRST regulated domain selected on\n  // `decision_domains` (doc 235's own first-pass reduction of a multi-select\n  // field to one class — see the build log's [NEEDS]).\n  \"class:lending_financial\": \"the decision is a credit or lending decision\",\n  \"class:housing\": \"the decision is a housing decision\",\n  \"class:education\": \"the decision is an education decision\",\n  \"class:hiring_admission\": \"the decision is a hiring or admission decision\",\n  \"class:work_allocation\": \"the decision is a work-allocation, scheduling, or compensation decision\",\n  \"class:employment_action\": \"the decision is a promotion, demotion, suspension, or termination decision\",\n  \"class:healthcare\": \"the decision is a healthcare decision\",\n\n  // — flags (RULE_PRODUCT_REGISTRY-style HOOK_PRODUCT_REGISTRY.admt.typed_state_vocabulary.flags) —\n  \"flag:significant_decision\": \"the system makes a covered significant decision\",\n  \"flag:no_human_review\": \"the decision is made without any human review\",\n  \"flag:qualifying_human_review\": \"a human reviewer has authority to change the decision\",\n  \"flag:solely_advertising\": \"the system is used solely for advertising\",\n  \"flag:vendor_hosted\": \"the system is hosted by a third-party vendor\",\n  \"flag:biometric_model\": \"the system uses a biometric, emotion-recognition, or identity-verification model\",\n  \"flag:full_opt_out\": \"the company provides a full opt-out\",\n  \"flag:human_appeal_exception\": \"the company relies on the human-appeal exception instead of a full opt-out\",\n  \"flag:hiring_admission_exception\": \"the company relies on the hiring or admission exception instead of a full opt-out\",\n  \"flag:work_allocation_exception\": \"the company relies on the work-allocation or compensation exception instead of a full opt-out\",\n\n  // — instruments (RULE_PRODUCT_REGISTRY.admt.instrument_scope) —\n  \"instrument:CPPA ADMT Regulations\": \"the system is assessed under the CPPA's ADMT regulations\",\n\n  // — state: atoms — ONE PHRASE PER CLOSED OPTION the hook drafter may emit.\n  // Covers a first-wave subset of ADMT's closed intake options (a handful\n  // of the highest-value fields, not the whole contract) — the drafter\n  // (generate-corpus-hooks/_local/vocabulary.ts, STATE_ATOM_ENUMS) would\n  // need entries added for these paths before a hook drafted against them\n  // could pass verification; see doc 235's [NEEDS].\n\n  // human review (intake.human_review — the four closed options)\n  \"state:intake.human_review=Yes — reviewer knows how to interpret output, reviews it plus other info, and has authority to change the decision\":\n    \"the company reports a qualifying human reviewer — one who understands the output, reviews it together with other information, and can change the decision\",\n  \"state:intake.human_review=Partial — reviewer sees the output but cannot override it\":\n    \"the company reports a reviewer who sees the output but cannot override it\",\n  \"state:intake.human_review=No — fully automated, no human review\":\n    \"the company reports the decision is fully automated, with no human review\",\n  \"state:intake.human_review=Not applicable / unsure\":\n    \"the company has not resolved whether a human reviews the decision\",\n\n  // solely advertising (intake.admt_detail.solely_advertising)\n  \"state:intake.admt_detail.solely_advertising=Yes — solely advertising\":\n    \"the company reports the system is used solely for advertising\",\n  \"state:intake.admt_detail.solely_advertising=No\":\n    \"the company reports the system is used for something beyond advertising\",\n\n  // notice purpose specificity (intake.notice_has_specific_purpose)\n  \"state:intake.notice_has_specific_purpose=Yes\":\n    \"the company reports its Pre-use Notice states a specific purpose\",\n  \"state:intake.notice_has_specific_purpose=No — uses generic language\":\n    \"the company reports its Pre-use Notice uses generic language rather than a specific purpose\",\n  \"state:intake.notice_has_specific_purpose=We have not yet created a Pre-use Notice\":\n    \"the company has not yet created a Pre-use Notice\",\n\n  // opt-out description in the notice (intake.notice_has_opt_out_desc)\n  \"state:intake.notice_has_opt_out_desc=Yes — with specific opt-out instructions\":\n    \"the company reports its notice gives specific opt-out instructions\",\n  \"state:intake.notice_has_opt_out_desc=Mentions opt-out but without clear instructions\":\n    \"the company reports its notice mentions opt-out but gives no clear instructions\",\n  \"state:intake.notice_has_opt_out_desc=No\":\n    \"the company reports its notice does not describe an opt-out\",\n  \"state:intake.notice_has_opt_out_desc=We rely on an exception and describe appeal rights instead\":\n    \"the company reports it relies on an exception and describes appeal rights instead of an opt-out\",\n  \"state:intake.notice_has_opt_out_desc=We rely on an exception and the notice identifies the specific exception\":\n    \"the company reports its notice identifies the specific exception it relies on\",\n\n  // access response timeline (intake.access_response_timeline)\n  \"state:intake.access_response_timeline=Within 45 calendar days (standard)\":\n    \"the company reports a standard 45-calendar-day access response timeline\",\n  \"state:intake.access_response_timeline=Within 45 days with documented 45-day extension capability\":\n    \"the company reports a 45-day response timeline with a documented extension capability\",\n  \"state:intake.access_response_timeline=Our process is not yet defined\":\n    \"the company reports its access response process is not yet defined\",\n\n  // human-review override authority (intake.admt_detail.hi_authority_override)\n  \"state:intake.admt_detail.hi_authority_override=Yes\":\n    \"the company reports its reviewer has authority to change the decision\",\n  \"state:intake.admt_detail.hi_authority_override=No\":\n    \"the company reports its reviewer does not have authority to change the decision\",\n\n  // nondiscrimination testing (intake.admt_detail.nondiscrimination_testing)\n  \"state:intake.admt_detail.nondiscrimination_testing=Yes — documented testing record\":\n    \"the company reports a documented nondiscrimination testing record\",\n  \"state:intake.admt_detail.nondiscrimination_testing=Testing performed but not documented\":\n    \"the company reports nondiscrimination testing was performed but not documented\",\n  \"state:intake.admt_detail.nondiscrimination_testing=No testing performed\":\n    \"the company reports no nondiscrimination testing was performed\",\n  \"state:intake.admt_detail.nondiscrimination_testing=Unsure\":\n    \"the company has not resolved whether nondiscrimination testing was performed\",\n};\n\n// ── [RATIFY — DRAFT, unratified] — the sentence shapes ───────────────────\n//\n// Structurally identical slot grammar to LIA's/DPIA's/Risk's own shapes\n// (doc 213 §5 / doc 222 §4) — S1-S5b/S6x reused verbatim, since their\n// wording names no product-specific legal test by name. S6 alone is\n// reworded: LIA's original names \"legitimate interests\" explicitly, which\n// has no ADMT analogue; ADMT's S6 instead names \"the {factor} question\" —\n// the same generalisation this build's doc 235 log documents was needed\n// before this shape could serve a product whose eight factors are not one\n// named three-part test.\n\nexport const ADMT_HOOK_SHAPES: Readonly<Record<\"S1\" | \"S2\" | \"S3\" | \"S4\" | \"S5a\" | \"S5b\" | \"S6\" | \"S6x\", string>> = {\n  S1:\n    \"The company has stated that {customer_fact}. In {authority}, {regulator} {verb} that where {fact_pattern}, {finding}. That finding supports the company's position on {factor}. ({citation}; {status}.)\",\n  S2:\n    \"The company has stated that {customer_fact}. In {authority}, {regulator} found that where {fact_pattern}, {finding}. That finding cuts against the company's position on {factor}, and the Section {section} finding reflects it. ({citation}; {status}.)\",\n  S3:\n    \"In {authority}, {regulator} found that where {fact_pattern}, {finding}. That finding turned on the fact that {source_fact}; on this record the company has instead stated that {record_fact}. The decision marks a boundary rather than a finding against the company. ({citation}; {status}.)\",\n  S4:\n    \"In {authority}, {regulator} found that where {fact_pattern}, {finding}. The company has stated that {customer_fact}. That decision is {status}; it is noted as a boundary and is not applied. ({citation}.)\",\n  S5a:\n    \"In {authority}, {regulator} {verb} that {proposition}, subject to {condition}. That guidance is relevant to the company's position on {factor}; whether its condition is satisfied is addressed in Section {section}. ({citation}; {status}.)\",\n  S5b:\n    \"In {authority}, {regulator} {verb} that {proposition}, subject to {condition}. That guidance is relevant to the company's position on {factor}; whether its condition is satisfied is addressed in Section {section}. The facts identified in Section {section} satisfy that stated condition. ({citation}; {status}.)\",\n  S6:\n    \"The company has stated that {record_fact}. In {authority}, {regulator} {verb} that {proposition}, subject to {condition}, but does not address the {factor} question where {record_fact}. The determination in Section {section} therefore rests on the separately identified rules and facts, not on that guidance. ({citation}; {status}.)\",\n  S6x:\n    \"The company has stated that {record_fact}. In {authority}, {regulator} {verb} that {proposition}, subject to {condition}, and that {exclusion_paraphrase}; that exclusion applies to processing of the kind the company describes, and the Section {section} finding reflects it. ({citation}; {status}.)\",\n};\n\n// ── [RATIFY — DRAFT, unratified] — concept equivalence ───────────────────\n//\n// Two atoms naming the same underlying fact share a concept; the render\n// dedupes `{customer_fact}` by concept (doc 222 §2.3). An atom absent here\n// is its own concept.\n\nexport const ADMT_ATOM_CONCEPTS: Readonly<Record<string, string>> = {\n  \"flag:no_human_review\": \"no_human_review\",\n  \"state:intake.human_review=No — fully automated, no human review\": \"no_human_review\",\n  \"flag:qualifying_human_review\": \"qualifying_human_review\",\n  \"state:intake.human_review=Yes — reviewer knows how to interpret output, reviews it plus other info, and has authority to change the decision\": \"qualifying_human_review\",\n  \"state:intake.admt_detail.hi_authority_override=Yes\": \"qualifying_human_review\",\n  \"flag:solely_advertising\": \"solely_advertising\",\n  \"state:intake.admt_detail.solely_advertising=Yes — solely advertising\": \"solely_advertising\",\n};\n\n/** The concept an atom names — itself when the table has no entry. */\nexport function admtAtomConcept(atom: string): string {\n  return ADMT_ATOM_CONCEPTS[atom] ?? atom;\n}\n\n// ── [RATIFY — DRAFT, unratified] — factor phrases: the `{factor}` slot,\n// without a leading article (every shape supplies \"the\" or \"on\") ─────────\n//\n// The eight `factor_id` values are ADMT's own CAM vocabulary\n// (admt-corpus-map.ts's `factor_id` field — the same eight strings\n// `buildFactorMatrixTable()` / `deriveAdmtFiredStates()` already key on),\n// used directly as `bears_on_element` (an identity map — ADMT's factors are\n// already flat, not grouped into a three-part test the way LIA's are; see\n// generate-corpus-hooks/_local/admt-factor-element.ts).\n\nexport const ADMT_FACTOR_PHRASES: Readonly<Record<string, string>> = {\n  \"Significant decision\": \"the significant-decision determination\",\n  \"Human involvement\": \"the human-involvement determination\",\n  \"Advertising exclusion\": \"the advertising-exclusion determination\",\n  \"Notice delivery\": \"the Pre-use Notice delivery\",\n  \"Notice content\": \"the Pre-use Notice content\",\n  \"Opt-out pathway\": \"the opt-out or exception pathway\",\n  \"Access process\": \"the access and explanation process\",\n  \"Vendor dependency\": \"the vendor-dependency determination\",\n};\n\n// ── [RATIFY — DRAFT, unratified] — source status labels ──────────────────\n//\n// Reused byte-for-byte from LIA_SOURCE_STATUS_LABELS: these describe the\n// CITED AUTHORITY's own kind and weight (a supervisory-authority decision,\n// EDPB guidance, an Article 29 Working Party opinion), which is unchanged\n// whether the authority is cited into an LIA, DPIA, Risk, or ADMT report —\n// an ADMT hook citing a GDPR enforcement decision by analogy still cites a\n// \"supervisory-authority decision,\" so this vocabulary is genuinely\n// product-agnostic, not copied blind. A CPPA Final Statement of Reasons\n// label (the FSOR source ADMT's own 38 dark FC rows already draw on) is\n// added here as a new entry — the ADMT-specific addition beyond LIA's set.\n\nexport const ADMT_SOURCE_STATUS_LABELS: Readonly<Record<string, string>> = {\n  edpb_guidelines_final: \"EDPB guidelines — interpretive guidance, not binding law\",\n  edpb_opinion: \"EDPB Article 64 opinion — Board opinion, not a judicial decision\",\n  wp29_opinion: \"Article 29 Working Party opinion — historical interpretive guidance\",\n  regulator_guidance: \"regulatory guidance — non-binding\",\n  sa_decision: \"supervisory-authority decision — persuasive, non-binding outside its jurisdiction\",\n  sa_decision_affirmed: \"supervisory-authority decision, affirmed on appeal\",\n  sa_decision_appeal_pending: \"under appeal\",\n  // ADMT-specific addition, mirroring doc 231's own CPPA FSOR label\n  // (\"CPPA Final Statement of Reasons — agency position, primary regulator\n  // commentary\"), for the 38 already-curated cppa_fsor_commentary FC rows\n  // this build's own vocabulary would eventually draft hooks against.\n  cppa_fsor_commentary: \"CPPA Final Statement of Reasons — agency position, primary regulator commentary\",\n};\n\n// ── RATIFIED by the CEO 2026-09-08 (byte-mirrored from LIA_APPEAL_SENTENCE,\n// run-li-assessment/_local/corpus/maps/lia-hooks.ts) — the appeal sentence ─\n\nexport const ADMT_APPEAL_SENTENCE = \"This matter is subject to an appeal which could invalidate this ruling.\";\n\nexport const ADMT_SETTLEDNESS_LABELS: Readonly<Record<\"R1\" | \"R2\" | \"R3\" | \"R4\", string>> = {\n  R1: \"adopted guidance or settled authority\",\n  R2: \"a settled line of decisions\",\n  R3: \"a single supervisory authority's decision\",\n  R4: \"under appeal / contested\",\n};\n";
